<?php
declare(strict_types=1);
namespace App\Controllers; use App\Core\Request;use App\Core\View;use App\Core\Response;use App\Core\Session;use App\Middleware\PermissionMiddleware;use App\Repositories\AccountRepository;
final class AccountController { public function index(Request $r):void{PermissionMiddleware::require('accounts.view');$rows=(new AccountRepository())->allVisible(auth_user());View::render('accounts/index',compact('rows'));} public function store(Request $r):void{PermissionMiddleware::require('accounts.create');verify_csrf();(new AccountRepository())->create($r->all(),(int)Session::get('user_id'));Session::flash('success','Account created.');Response::redirect('/accounts');} public function update(Request $r,string $id):void{PermissionMiddleware::require('accounts.edit');verify_csrf();(new AccountRepository())->update((int)$id,$r->all(),(int)Session::get('user_id'));Session::flash('success','Account updated.');Response::redirect('/accounts');} public function delete(Request $r,string $id):void{PermissionMiddleware::require('accounts.delete');verify_csrf();(new AccountRepository())->delete((int)$id,(int)Session::get('user_id'));Session::flash('success','Account deleted.');Response::redirect('/accounts');}}
